import React from "react";
import "./ContentContainer.css";
import SideTasksContainer from "./SideTasksContainer/SideTasksContainer";
import Carousel from "../Carousel/Carousel";

const ContentContainer = () => {
  return (
    <div className="content-container content-container-grid ">

      <Carousel>
        <div style={{ backgroundColor: "red" }}>Slide 1</div>
        <div style={{ backgroundColor: "blue" }}>Slide 2</div>
        <div style={{ backgroundColor: "green" }}>Slide 3</div>
      </Carousel>

      <SideTasksContainer />
    </div>
  );
};

export default ContentContainer;
